import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.e4u2V5E7.js";const p=JSON.parse('{"title":"Authentication","description":"Authentication reference documentation","frontmatter":{"title":"Authentication","description":"Authentication reference documentation"},"headers":[],"relativePath":"knowledge/authentication.md","filePath":"knowledge/authentication.md","lastUpdated":1784485118000}'),s={name:"knowledge/authentication.md"};function n(r,e,l,c,d,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><h1 id="authentication-patterns-—-knowledge-base" tabindex="-1">Authentication Patterns — Knowledge Base <a class="header-anchor" href="#authentication-patterns-—-knowledge-base" aria-label="Permalink to &quot;Authentication Patterns — Knowledge Base&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Authentication is the process of verifying who a user is. This knowledge base covers authentication strategies, implementation patterns, and security considerations for modern web applications built with Next.js and Supabase. Choosing the right auth strategy impacts security, user experience, and development velocity.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="authentication-vs-authorization" tabindex="-1">Authentication vs Authorization <a class="header-anchor" href="#authentication-vs-authorization" aria-label="Permalink to &quot;Authentication vs Authorization&quot;">​</a></h3><p><strong>Authentication (AuthN)</strong> answers &quot;Who are you?&quot; — verifying identity through credentials, tokens, or biometrics. <strong>Authorization (AuthZ)</strong> answers &quot;What can you do?&quot; — determining permissions after identity is established.</p><p>These are separate concerns; authentication always precedes authorization.</p><h3 id="token-based-authentication-jwt" tabindex="-1">Token-Based Authentication (JWT) <a class="header-anchor" href="#token-based-authentication-jwt" aria-label="Permalink to &quot;Token-Based Authentication (JWT)&quot;">​</a></h3><p>JSON Web Tokens encode user claims in a signed, tamper-proof token. JWTs contain three parts: header (algorithm), payload (claims), and signature.</p><p><strong>JWT lifecycle:</strong></p><ol><li>User authenticates with credentials</li><li>Server validates credentials and issues JWT</li><li>Client stores JWT (typically in httpOnly cookie)</li><li>Client sends JWT with each request</li><li>Server verifies signature and extracts claims</li><li>Token expires; client uses refresh token to obtain new JWT</li></ol><p><strong>Key claims:</strong> <code>sub</code> (subject/user ID), <code>exp</code> (expiration), <code>iat</code> (issued at), <code>iss</code> (issuer), <code>aud</code> (audience)</p><h3 id="session-based-authentication" tabindex="-1">Session-Based Authentication <a class="header-anchor" href="#session-based-authentication" aria-label="Permalink to &quot;Session-Based Authentication&quot;">​</a></h3><p>Server maintains session state; client holds only a session identifier (usually in a cookie).</p><p><strong>Advantages:</strong> Server can revoke sessions instantly, smaller client payload, no client-side token storage concerns. <strong>Disadvantages:</strong> Requires server-side storage, doesn&#39;t scale easily without distributed session store (Redis).</p><h3 id="oauth-2-0-and-openid-connect" tabindex="-1">OAuth 2.0 and OpenID Connect <a class="header-anchor" href="#oauth-2-0-and-openid-connect" aria-label="Permalink to &quot;OAuth 2.0 and OpenID Connect&quot;">​</a></h3><p><strong>OAuth 2.0</strong> is an authorization framework that enables third-party applications to obtain limited access to a service. <strong>OpenID Connect (OIDC)</strong> is an identity layer built on top of OAuth 2.0 that provides authentication.</p><p><strong>OAuth 2.0 flows:</strong></p><ul><li><strong>Authorization Code Flow</strong> — Server-side apps (most secure; PKCE required for SPAs)</li><li><strong>Client Credentials Flow</strong> — Machine-to-machine (no user involved)</li><li><strong>Implicit Flow</strong> — Deprecated for security reasons; avoid</li><li><strong>Device Authorization Flow</strong> — Smart TVs, CLI tools</li></ul><p><strong>OIDC adds:</strong> ID tokens (JWT), userinfo endpoint, standard scopes (<code>openid</code>, <code>profile</code>, <code>email</code>)</p><h3 id="password-hashing" tabindex="-1">Password Hashing <a class="header-anchor" href="#password-hashing" aria-label="Permalink to &quot;Password Hashing&quot;">​</a></h3><p>Never store plaintext passwords. Use purpose-built password hashing algorithms:</p><ul><li><strong>Argon2id</strong> (recommended) — Winner of the Password Hashing Competition; memory-hard, GPU-resistant</li><li><strong>bcrypt</strong> — Battle-tested, adaptive; use cost factor ≥12</li><li><strong>scrypt</strong> — Memory-hard alternative; less widely adopted than Argon2</li></ul><p><strong>Key principles:</strong></p><ul><li>Generate unique salt per password (bcrypt does this automatically)</li><li>Use adaptive cost factors that make hashing slow enough to resist brute force</li><li>Never implement your own hashing; use established libraries</li></ul><h3 id="multi-factor-authentication-mfa" tabindex="-1">Multi-Factor Authentication (MFA) <a class="header-anchor" href="#multi-factor-authentication-mfa" aria-label="Permalink to &quot;Multi-Factor Authentication (MFA)&quot;">​</a></h3><p>MFA requires two or more verification factors: something you know (password), something you have (phone/key), something you are (biometrics).</p><p><strong>Common methods:</strong> TOTP (Time-based One-Time Password), SMS codes (weaker), hardware keys (WebAuthn/FIDO2), biometrics, backup codes</p><h3 id="magic-links-passwordless" tabindex="-1">Magic Links (Passwordless) <a class="header-anchor" href="#magic-links-passwordless" aria-label="Permalink to &quot;Magic Links (Passwordless)&quot;">​</a></h3><p>User provides email → receives a unique, time-limited link → clicks link → authenticated. This eliminates passwords entirely.</p><p><strong>Security considerations:</strong> Rate-limit email sending, short token expiry (5-10 minutes), single-use tokens, secure token generation (CSPRNG)</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use httpOnly, Secure, SameSite cookies for tokens</strong> — Prevents XSS access to tokens and provides CSRF protection; avoid localStorage for auth tokens</li><li><strong>Implement refresh token rotation</strong> — Issue short-lived access tokens (15min) with longer-lived refresh tokens; rotate refresh tokens on each use</li><li><strong>Enforce strong password requirements</strong> — Follow NIST 800-63b: minimum 8 characters, check against breached password databases, no composition rules that reduce usability</li><li><strong>Rate-limit authentication attempts</strong> — Implement progressive delays after failed attempts; lock accounts after repeated failures with unlock mechanism</li><li><strong>Validate tokens on every request</strong> — Never trust client assertions; verify JWT signature, expiration, issuer, and audience on each API call</li><li><strong>Use Supabase Auth helpers for Next.js</strong> — <code>@supabase/ssr</code> provides proper cookie-based session management; avoid manually managing tokens</li><li><strong>Implement account recovery securely</strong> — Password reset links should be single-use, time-limited, and sent only to verified email addresses</li><li><strong>Log authentication events</strong> — Record login, logout, password changes, and MFA events for audit trails and security monitoring</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Storing JWT in localStorage</strong> — Accessible to any XSS attack; use httpOnly cookies instead which JavaScript cannot access</li><li><strong>Using long-lived access tokens</strong> — Tokens without expiry windows cannot be revoked; use short expiry (15min) with refresh rotation</li><li><strong>Comparing passwords with <code>===</code></strong> — Always use constant-time comparison functions to prevent timing attacks on password verification</li><li><strong>Sending passwords in URL query parameters</strong> — Query parameters are logged in server logs, browser history, and referrer headers; always use POST body</li><li><strong>Client-side token validation only</strong> — Client validation improves UX but provides no security; server must always validate independently</li><li><strong>Reusing session tokens across environments</strong> — Development, staging, and production must use separate secrets and token issuers</li><li><strong>Missing CSRF protection</strong> — State-changing requests via cookies need CSRF tokens or SameSite=Strict cookie attribute</li><li><strong>Hardcoded authentication secrets</strong> — JWT signing keys, OAuth client secrets, and API keys must be in environment variables, never in code</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Not using HTTPS in development</strong> — Auth cookies without Secure flag are sent over HTTP; always use HTTPS even locally with self-signed certs</li><li><strong>Forgetting to invalidate server-side sessions on logout</strong> — Clearing client cookies is not sufficient; server must mark session as invalid</li><li><strong>Over-permissioning service role keys</strong> — <code>SUPABASE_SERVICE_ROLE_KEY</code> bypasses RLS; only use for specific server-side operations that require it</li><li><strong>Not handling token refresh failures gracefully</strong> — When refresh tokens expire, redirect to login without showing cryptic errors</li><li><strong>Exposing user IDs in URLs</strong> — Auto-incrementing IDs in URLs leak information; use UUIDs for public-facing identifiers</li><li><strong>Relying solely on client-side authentication checks</strong> — UI hiding elements is not authorization; API routes must enforce access control</li><li><strong>Not implementing proper session timeout</strong> — Both idle timeout and absolute timeout should be configured; re-authenticate for sensitive operations</li><li><strong>Using weak random for token generation</strong> — Always use <code>crypto.randomUUID()</code> or equivalent CSPRNG; never use <code>Math.random()</code></li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommended Approach</th></tr></thead><tbody><tr><td>SaaS application</td><td>Supabase Auth + OAuth providers (Google, GitHub)</td></tr><tr><td>Internal admin tool</td><td>Simple JWT with role-based access, no MFA required</td></tr><tr><td>Financial/healthcare app</td><td>Password + MFA (WebAuthn preferred), short token expiry</td></tr><tr><td>Mobile-first app</td><td>Supabase Auth with PKCE flow, biometric login</td></tr><tr><td>API-only backend</td><td>OAuth 2.0 Client Credentials or API key authentication</td></tr><tr><td>Quick prototype</td><td>Magic link authentication (fastest to implement)</td></tr><tr><td>Multi-tenant SaaS</td><td>Supabase Auth + RLS policies per organization</td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Supabase Auth Documentation: <a href="https://supabase.com/docs/guides/auth" target="_blank" rel="noreferrer">https://supabase.com/docs/guides/auth</a></li><li>NextAuth.js Documentation: <a href="https://next-auth.js.org/" target="_blank" rel="noreferrer">https://next-auth.js.org/</a></li><li>OWASP Authentication Cheat Sheet: <a href="https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html" target="_blank" rel="noreferrer">https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html</a></li><li>NIST SP 800-63b (Digital Identity Guidelines): <a href="https://pages.nist.gov/800-63-3/sp800-63b.html" target="_blank" rel="noreferrer">https://pages.nist.gov/800-63-3/sp800-63b.html</a></li><li>RFC 7519 (JWT): <a href="https://datatracker.ietf.org/doc/html/rfc7519" target="_blank" rel="noreferrer">https://datatracker.ietf.org/doc/html/rfc7519</a></li><li>RFC 6749 (OAuth 2.0): <a href="https://datatracker.ietf.org/doc/html/rfc6749" target="_blank" rel="noreferrer">https://datatracker.ietf.org/doc/html/rfc6749</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li><strong>Supabase Auth setup:</strong> Initialize with <code>createBrowserClient</code> and <code>createServerClient</code> from <code>@supabase/ssr</code> for proper cookie handling in Next.js App Router</li><li><strong>NextAuth.js alternative:</strong> If not using Supabase, NextAuth.js v5 provides built-in OAuth, CSRF protection, and session management</li><li><strong>Development testing:</strong> Use Supabase CLI to run auth locally; test password flows, OAuth redirects, and MFA enrollment</li><li><strong>Migration strategy:</strong> When switching auth providers, support both old and new auth simultaneously during transition period</li><li><strong>Monitoring:</strong> Set up alerts for abnormal login patterns: multiple failed attempts, logins from unusual locations, bulk account creation</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',46)])])}const g=t(s,[["render",n]]);export{p as __pageData,g as default};
